import type { Assessment, Career } from "@shared/schema";
import type { RiasecScores } from "./matching";

/**
 * Premium Narrative Generator
 * Generates enhanced, personalized career insights for premium-tier assessments
 * using RIASEC personality and CVQ values data.
 *
 * Supports English (default) and Arabic output via the `language` field in
 * NarrativeContext.  The "Why This Career?" (premiumReasoning) section is
 * generated by the LLM pipeline when an API key is configured; these heuristic
 * functions serve as the fallback and as the primary source for workStyleFit,
 * strengthsGrowth, and enhancedActionSteps.
 */

interface NarrativeContext {
  assessment: Assessment;
  career: Career;
  riasecScores?: RiasecScores;
  cvqScores?: Record<string, any>;
  overallScore: number;
  language?: string;
}

// ===== Small helpers =====

function matchQuality(score: number, lang: string): string {
  if (lang === "ar") {
    if (score >= 80) return "متوافق للغاية";
    if (score >= 70) return "متوافق بشكل قوي";
    return "متوافق بشكل جيد";
  }
  if (score >= 80) return "highly compatible";
  if (score >= 70) return "strong";
  return "good";
}

/** Return the career's localised title, falling back to the English title. */
function localTitle(career: Career, lang: string): string {
  return lang === "ar" && career.titleAr ? career.titleAr : career.title;
}

// ===== RIASEC descriptions =====

function getRiasecThemeDescription(code: string, lang: string): string {
  const en: Record<string, string> = {
    R: "You have a Realistic personality—you prefer hands-on work and practical problem-solving",
    I: "You have an Investigative personality—you enjoy analyzing data and solving complex problems",
    A: "You have an Artistic personality—you value creativity and self-expression",
    S: "You have a Social personality—you thrive on helping others and building relationships",
    E: "You have an Enterprising personality—you enjoy leading projects and persuading others",
    C: "You have a Conventional personality—you excel at organization and attention to detail",
  };
  const ar: Record<string, string> = {
    R: "لديك شخصية واقعية — تفضل العمل العملي وحل المشكلات التطبيقية",
    I: "لديك شخصية استقصائية — تستمتع بتحليل البيانات وحل المشكلات المعقدة",
    A: "لديك شخصية فنية — تقدّر الإبداع والتعبير الذاتي",
    S: "لديك شخصية اجتماعية — تزدهر في مساعدة الآخرين وبناء العلاقات",
    E: "لديك شخصية مغامِرة — تستمتع بقيادة المشاريع وإقناع الآخرين",
    C: "لديك شخصية تقليدية — تتميز في التنظيم والاهتمام بالتفاصيل",
  };
  return (lang === "ar" ? ar : en)[code] ?? "";
}

function getRiasecCareerFit(code: string, title: string, lang: string): string {
  if (lang === "ar") {
    const ar: Record<string, string> = {
      R: `تتضمن وظائف ${title} في الغالب نتائج ملموسة ومهارات تقنية تتناسب مع طبيعتك العملية`,
      I: `يتطلب مجال ${title} التفكير التحليلي ومهارات البحث التي تُحفزك وتشحن طاقتك`,
      A: `يُتيح لك مجال ${title} فرصاً لحل المشكلات بإبداع والتفكير الابتكاري الذي يُشغّل عقلك الفني`,
      S: `يتضمن مجال ${title} تفاعلات ذات معنى ومساعدة الآخرين، وهو ما يتوافق تماماً مع طبيعتك الاجتماعية`,
      E: `يُوفر مجال ${title} فرص قيادة والقدرة على قيادة المبادرات، مما يتناسب مع روحك الريادية`,
      C: `يُقدّر مجال ${title} الأسلوب المنظم والعمل الدقيق الذي تتفوق فيه بشكل طبيعي`,
    };
    return ar[code] ?? `يتوافق مجال ${title} مع نقاط قوتك ومهاراتك`;
  }
  const en: Record<string, string> = {
    R: `${title} roles often involve tangible outcomes and technical skills that match your practical nature`,
    I: `${title} requires the analytical thinking and research skills that energize you`,
    A: `${title} provides opportunities for creative problem-solving and innovative thinking that engage your artistic mindset`,
    S: `${title} involves meaningful interactions and helping others, which aligns perfectly with your people-oriented nature`,
    E: `${title} offers leadership opportunities and the chance to drive initiatives, matching your entrepreneurial spirit`,
    C: `${title} values the structured approach and precise work that you naturally excel at`,
  };
  return en[code] ?? `${title} aligns with your strengths and skills`;
}

// ===== Values descriptions =====

function getValueDescription(value: string, lang: string): string {
  const en: Record<string, string> = {
    achievement: "success and personal accomplishment",
    benevolence: "helping others and making a positive impact",
    universalism: "fairness, equality, and social justice",
    self_direction: "independence and creative freedom",
    security: "stability and safety",
    power: "influence and leadership",
    hedonism: "enjoyment and work-life balance",
  };
  const ar: Record<string, string> = {
    achievement: "النجاح والإنجاز الشخصي",
    benevolence: "مساعدة الآخرين وإحداث أثر إيجابي",
    universalism: "العدل والمساواة والعدالة الاجتماعية",
    self_direction: "الاستقلالية والحرية الإبداعية",
    security: "الاستقرار والأمان",
    power: "التأثير والقيادة",
    hedonism: "الاستمتاع بالحياة والتوازن بين العمل والحياة",
  };
  return (lang === "ar" ? ar : en)[value] ?? value;
}

function getValueCareerAlignment(value: string, title: string, lang: string): string {
  if (lang === "ar") {
    const ar: Record<string, string> = {
      achievement: `يُوفر مجال ${title} معايير واضحة للنجاح وفرصاً لإثبات كفاءتك من خلال نتائج قابلة للقياس`,
      benevolence: `يُتيح لك مجال ${title} المساهمة بشكل هادف في حياة الآخرين وإحداث فرق ملموس في مجتمعك`,
      universalism: `يُوفر مجال ${title} فرصاً للترويج للعدل والمساهمة في بناء مجتمع أكثر إنصافاً`,
      self_direction: `يُتيح لك مجال ${title} الاستقلالية في اتخاذ القرار وحيزاً لحل المشكلات بإبداع`,
      security: `يُوفر مجال ${title} آفاقاً مهنية مستقرة ومسارات واضحة وظروف عمل موثوقة`,
      power: `يُوفر مجال ${title} فرصاً لتولي أدوار قيادية والتأثير في القرارات المهمة في مجالك`,
      hedonism: `يُمكن أن يُوفر مجال ${title} توازناً بين العمل والحياة ومرونة للاستمتاع بالحياة أثناء بناء مسيرة مهنية مُرضية`,
    };
    return ar[value] ?? `يتوافق مجال ${title} مع قيمك`;
  }
  const en: Record<string, string> = {
    achievement: `${title} provides clear benchmarks for success and opportunities to demonstrate your competence through measurable results`,
    benevolence: `${title} allows you to contribute meaningfully to others' lives and make a tangible difference in your community`,
    universalism: `${title} offers opportunities to promote fairness and contribute to creating a more just and equitable society`,
    self_direction: `${title} provides autonomy in decision-making and room for creative problem-solving that respects your independence`,
    security: `${title} offers stable career prospects with clear professional pathways and reliable working conditions`,
    power: `${title} provides opportunities to take on leadership roles and influence important decisions in your field`,
    hedonism: `${title} can offer work-life balance and the flexibility to enjoy life while building a fulfilling career`,
  };
  return en[value] ?? `aligns with your values`;
}

