function getRiasecTaskPreferences(theme: string, title: string, lang: string): string {
  if (lang === "ar") {
    const ar: Record<string, string> = {
      R: `بوصفك ${title}، ستستمتع بمهام مثل بناء النماذج الأولية وحل المشكلات التقنية والعمل مع الأدوات أو المعدات — وهي جميعها تتوافق مع تفضيلاتك العملية.`,
      I: `قد يشمل يومك المعتاد تحليل البيانات والبحث عن حلول للمشكلات المعقدة ووضع توصيات مبنية على أدلة — مهام تُشبع فضولك الفكري.`,
      A: `ستنجذب إلى المهام التي تنطوي على التصميم الإبداعي وتطوير حلول مبتكرة وصياغة عروض تقديمية مقنعة — عمل يُشغّل حواسك الفنية.`,
      S: `قد يتضمن يوم عملك تدريب الآخرين وتيسير اجتماعات الفريق وبناء علاقات مع أصحاب المصلحة — أنشطة تستثمر نقاط قوتك في التواصل الإنساني.`,
      E: `ستزدهر في مهام مثل تقديم الأفكار وقيادة فرق المشاريع والتفاوض مع الشركاء — عمل يستخدم قدراتك في الإقناع والقيادة.`,
      C: `سيتضمن يومك على الأرجح تنظيم الأنظمة وضمان الجودة والحفاظ على سجلات دقيقة — مهام تستثمر مهاراتك التنظيمية الاستثنائية.`,
    };
    return ar[theme] ?? `ستُشغّل مهامك اليومية كـ${title} نقاط قوتك واهتماماتك الطبيعية.`;
  }
  const en: Record<string, string> = {
    R: `As a ${title}, you'll enjoy tasks like building prototypes, troubleshooting technical issues, and working with tools or equipment—all of which align with your practical, hands-on preferences.`,
    I: `Your typical day might include analyzing data, researching solutions to complex problems, and developing evidence-based recommendations—tasks that satisfy your intellectual curiosity.`,
    A: `You'll gravitate toward tasks that involve creative design, developing innovative solutions, and crafting compelling presentations—work that engages your artistic sensibilities.`,
    S: `Your workday might involve mentoring others, facilitating team meetings, and building stakeholder relationships—activities that leverage your interpersonal strengths.`,
    E: `You'll thrive on tasks like pitching ideas, leading project teams, and negotiating with partners—work that uses your persuasive and leadership abilities.`,
    C: `Your day will likely include organizing systems, ensuring quality control, and maintaining detailed records—tasks that utilize your exceptional organizational skills.`,
  };
  return en[theme] ?? `Your daily tasks in ${title} will engage your natural strengths and interests.`;
}

