// ===== Helper =====

function getTopRiasecThemes(scores: RiasecScores): string[] {
  return (["R", "I", "A", "S", "E", "C"] as const)
    .map((code) => ({ code, score: scores[code] }))
    .sort((a, b) => b.score - a.score)
    .map((t) => t.code)
    .slice(0, 3);
}

// ===== Exported narrative generators =====

/**
 * Generate expanded "Why This Career?" reasoning (5-6 paragraphs).
 * Used as the heuristic fallback when the LLM service is unavailable.
 */
export function generateEnhancedReasoning(context: NarrativeContext): string {
  const { assessment, career, riasecScores, cvqScores, overallScore, language = "en" } = context;
  const lang = language === "ar" ? "ar" : "en";
  const title = localTitle(career, lang);
  const paragraphs: string[] = [];

  // Paragraph 1: Overall match introduction
  if (lang === "ar") {
    paragraphs.push(
      `يُعدّ مجال ${title} تطابقاً ${matchQuality(overallScore, lang)} لك، بنسبة ${overallScore.toFixed(1)}% بناءً على تقييمك الشامل. يتوافق هذا المجال المهني مع مزيجك الفريد من الاهتمامات وسمات الشخصية والقيم الشخصية.`
    );
  } else {
    paragraphs.push(
      `${title} is a ${matchQuality(overallScore, lang)} match for you, scoring ${overallScore.toFixed(1)}% based on your comprehensive assessment. This career aligns with your unique combination of interests, personality traits, and personal values.`
    );
  }

  // Paragraph 2: RIASEC personality match
  if (riasecScores) {
    const primary = getTopRiasecThemes(riasecScores)[0];
    const desc = getRiasecThemeDescription(primary, lang);
    const fit = getRiasecCareerFit(primary, title, lang);
    if (lang === "ar") {
      paragraphs.push(`${desc}. ${fit}. يُشير ملفك الشخصي إلى أنك ستجد هذا العمل مثيراً للاهتمام ومُرضياً بشكل طبيعي.`);
    } else {
      paragraphs.push(`${desc}. ${fit}. Your personality profile suggests you'll find this work naturally engaging and fulfilling.`);
    }
  }

  // Paragraph 3: Values alignment (CVQ)
  if (cvqScores?.top3 && Array.isArray(cvqScores.top3)) {
    const primary = cvqScores.top3[0] as string;
    const primaryDesc = getValueDescription(primary, lang);
    const alignment = getValueCareerAlignment(primary, title, lang);
    if (lang === "ar") {
      paragraphs.push(`ما يهمك أكثر — ${primaryDesc} — ينعكس في هذا الاختيار المهني. ${alignment}. هذا التوافق في القيم يعني أنك أكثر احتمالاً لإيجاد الرضا والمعنى على المدى البعيد في عملك.`);
    } else {
      paragraphs.push(`What matters most to you—${primaryDesc}—is reflected in this career choice. ${alignment}. This values alignment means you're more likely to find long-term satisfaction and meaning in your work.`);
    }
  }

  // Paragraph 4: Subject & skills connection
  if (assessment.favoriteSubjects) {
    const subjects = assessment.favoriteSubjects as string[];
    const relevantSubjects = subjects.filter((s) => career.relatedSubjects.includes(s));
    if (relevantSubjects.length === 0) {
      paragraphs.push(
        lang === "ar"
          ? `المهارات التحليلية وحل المشكلات التي تطورها في دراستك ستنتقل بشكل جيد إلى مجال ${title}.`
          : `The analytical and problem-solving skills you're developing in your coursework will transfer well to ${title}.`
      );
    } else {
      const subjectList = relevantSubjects.slice(0, 3).join(lang === "ar" ? " و" : ", ");
      paragraphs.push(
        lang === "ar"
          ? `اهتمامك بـ${subjectList} يدعم مسار هذه المهنة مباشرةً. تُشكّل المفاهيم والمهارات من هذه المواد الأساس لعمل ${title}. مع تقدمك، ستدرك كيف تنطبق المعرفة الأكاديمية على التحديات المهنية الواقعية، مما يجعل دراستك أكثر هدفاً وجاذبية.`
          : `Your interest in ${subjectList} directly supports this career path. The concepts and skills from these subjects form the foundation for ${title} work. As you advance, you'll see how classroom knowledge applies to real-world professional challenges, making your studies more purposeful and engaging.`
      );
    }
  }

  // Paragraph 5: Future outlook
  const skills = career.requiredSkills.slice(0, 3).join(lang === "ar" ? " و" : ", ");
  paragraphs.push(
    lang === "ar"
      ? `وبالنظر إلى المستقبل، يُوفر مجال ${title} إمكانات نمو قوية في سوق العمل الإماراتي. المهارات التي ستطورها — بما فيها ${skills} — تكتسب قيمة متزايدة مع تحديث الصناعات. يُتيح هذا المسار المهني فرصاً للتعلم المستمر والتقدم المهني المتوافق مع نقاط قوتك.`
      : `Looking ahead, ${title} offers strong growth potential in the UAE job market. The skills you'll develop—including ${skills}—are increasingly valuable as industries modernize. This career path provides opportunities for continuous learning and professional advancement aligned with your strengths.`
  );

  return paragraphs.join("\n\n");
}

/**
 * Generate "Your Work Style Fit" section.
 */
export function generateWorkStyleFit(context: NarrativeContext): string {
  const { career, riasecScores, language = "en" } = context;
  const lang = language === "ar" ? "ar" : "en";
  const title = localTitle(career, lang);
  const sections: string[] = [];

  if (riasecScores) {
    const topTheme = getTopRiasecThemes(riasecScores)[0];
    const collaborationLabel = lang === "ar" ? "**أسلوب التعاون الجماعي:**" : "**Team Collaboration:**";
    sections.push(`${collaborationLabel} ${getRiasecCollaborationStyle(topTheme, lang)}`);

    const tasksLabel = lang === "ar" ? "**المهام اليومية:**" : "**Daily Tasks:**";
    sections.push(`${tasksLabel} ${getRiasecTaskPreferences(topTheme, title, lang)}`);
  }

  return sections.join("\n\n");
}

/**
 * Generate "Personal Strengths & Growth Areas" section.
 */
export function generateStrengthsGrowth(context: NarrativeContext): string {
  const { riasecScores, cvqScores, language = "en" } = context;
  const lang = language === "ar" ? "ar" : "en";
  const sections: string[] = [];

  const strengths: string[] = [];
  if (riasecScores) {
    getTopRiasecThemes(riasecScores)
      .slice(0, 2)
      .forEach((theme) => strengths.push(getRiasecStrength(theme, lang)));
  }
  if (strengths.length > 0) {
    const label = lang === "ar" ? "**نقاط قوتك الأساسية:**" : "**Your Core Strengths:**";
    sections.push(`${label}\n${strengths.map((s, i) => `${i + 1}. ${s}`).join("\n")}`);
  }

  const growthAreas: string[] = [];
  if (cvqScores?.top3) {
    const lowestValue = (cvqScores.top3 as string[]).at(-1);
    if (lowestValue) growthAreas.push(getValueGrowthArea(lowestValue, lang));
  }
  if (growthAreas.length > 0) {
    const label = lang === "ar" ? "**مجالات النمو:**" : "**Areas for Growth:**";
    sections.push(`${label}\n${growthAreas.map((g, i) => `${i + 1}. ${g}`).join("\n")}`);
  }

  return sections.join("\n\n");
}

/**
 * Generate enhanced action steps (7 detailed steps with timelines).
 */
export function generateEnhancedActionSteps(context: NarrativeContext): string[] {
  const { assessment, career, language = "en" } = context;
  const lang = language === "ar" ? "ar" : "en";
  const title = localTitle(career, lang);
  const skills01 = career.requiredSkills.slice(0, 2).join(lang === "ar" ? " و" : " and ");
  const steps: string[] = [];

  if (lang === "ar") {
    steps.push(`**هذا الشهر:** ابحث في مجال ${title} من خلال مشاهدة مقاطع فيديو عن يوم في حياة المهنيين وقراءة ملفاتهم الشخصية لفهم المسؤوليات اليومية`);
    steps.push(`**خلال 3 أشهر:** تواصل مع محترف في مجال ${title} لإجراء مقابلة معلوماتية مدتها 20 دقيقة للتعرف على مسيرته المهنية ونصائحه`);

    if (assessment.favoriteSubjects && (assessment.favoriteSubjects as string[]).length > 0) {
      const topSubject = (assessment.favoriteSubjects as string[])[0];
      steps.push(`**خلال 6 أشهر:** تفوق في مادة ${topSubject} من خلال السعي للقيام بمشاريع متقدمة أو مسابقات لبناء المعرفة الأساسية لهذه المهنة`);
    }

    steps.push(`**خلال سنة:** ابدأ بتطوير مهارات أساسية مثل ${skills01} من خلال الدورات الإلكترونية أو الأنشطة المدرسية أو المشاريع الشخصية`);
    steps.push(`**السنتان 2-3:** اكتسب خبرة عملية من خلال التدريب الميداني أو العمل التطوعي أو الفرص بدوام جزئي في مجال ${career.category} لبناء سيرتك الذاتية وشبكة علاقاتك`);
    steps.push(`**السنة 3-4:** ابحث في الجامعات التي تُقدم برامج قوية في مجال ${career.category} وقدّم طلباتك، مع التركيز على المؤسسات ذات الروابط الصناعية والتدريب العملي`);
    steps.push(`**ما بعد السنة 4:** بعد إتمام ${career.educationLevel}، اسعَ للحصول على شهادات أو تدريب متخصص في المجالات الناشئة ضمن ${career.category} للحفاظ على تنافسيتك`);
  } else {
    steps.push(`**This Month:** Research ${title} careers by watching day-in-the-life videos and reading professional profiles to understand daily responsibilities`);
    steps.push(`**Next 3 Months:** Connect with a ${title} professional for a 20-minute informational interview to learn about their career journey and advice`);

    if (assessment.favoriteSubjects && (assessment.favoriteSubjects as string[]).length > 0) {
      const topSubject = (assessment.favoriteSubjects as string[])[0];
      steps.push(`**Next 6 Months:** Excel in ${topSubject} by seeking advanced projects or competitions to build foundational knowledge for this career`);
    }

    steps.push(`**Next Year:** Start building key skills like ${skills01} through online courses, school clubs, or personal projects`);
    steps.push(`**Years 2-3:** Gain hands-on experience through internships, volunteer work, or part-time opportunities in ${career.category} to build your resume and network`);
    steps.push(`**Year 3-4:** Research and apply to universities offering strong programs in ${career.category}, focusing on institutions with industry connections and practical training`);
    steps.push(`**Beyond Year 4:** After completing ${career.educationLevel}, pursue certifications or specialized training in emerging areas within ${career.category} to stay competitive`);
  }

  return steps;
}
